package com.luminor.tavernquest.data.local.database.dao
import androidx.room.*; import com.luminor.tavernquest.data.local.database.entity.TavernMemberEntity
@Dao interface TavernMemberDao{@Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun insert(v:TavernMemberEntity);@Query("SELECT * FROM tavern_member WHERE tavernId=:id") suspend fun getMembers(id:String):List<TavernMemberEntity>;@Query("SELECT * FROM tavern_member WHERE heroId=:heroId") suspend fun getForHero(heroId:String):List<TavernMemberEntity>;@Query("SELECT * FROM tavern_member WHERE tavernId=:id AND role='OWNER' LIMIT 1") suspend fun getOwner(id:String):TavernMemberEntity?;@Query("SELECT * FROM tavern_member WHERE tavernId=:tavernId AND heroId=:heroId LIMIT 1") suspend fun getForHero(tavernId:String,heroId:String):TavernMemberEntity?;@Query("DELETE FROM tavern_member WHERE tavernId=:tavernId AND heroId=:heroId") suspend fun leave(tavernId:String,heroId:String);@Query("DELETE FROM tavern_member") suspend fun deleteAll()}
